import pandas as pd


def run(inputs: dict) -> dict:
    def get_input(name):
        if name in inputs:
            return inputs[name]
        for k in inputs:
            if k.lower() == name.lower():
                return inputs[k]
        raise KeyError(name)

    dim = get_input('DIM_ACCOUNT').copy()
    stg = get_input('STG_ACCOUNT').copy()

    def is_na(x):
        return pd.isna(x)

    def plan_eq(a, b):
        a_na = is_na(a)
        b_na = is_na(b)
        if a_na and b_na:
            return True
        if a_na != b_na:
            return False
        return a == b

    # Build per-account version lists from existing dim state
    versions = {}
    for _, row in dim.iterrows():
        acc = row['account_id']
        versions.setdefault(acc, []).append({
            'plan': row['plan'],
            'start': row['eff_start_date'],
            'end': row['eff_end_date'],
            'is_current': row['is_current'],
        })

    # Sort staging rows: account_id, update_date ascending (stable)
    stg_sorted = stg.sort_values(by=['account_id', 'update_date'], kind='mergesort')

    for _, s in stg_sorted.iterrows():
        acc = s['account_id']
        plan = s['plan']
        upd = s['update_date']

        vlist = versions.setdefault(acc, [])

        if len(vlist) == 0:
            vlist.append({
                'plan': plan,
                'start': upd,
                'end': None,
                'is_current': 1,
            })
            continue

        # find the version covering upd: start <= upd < end (end NULL = open)
        covering = None
        for v in vlist:
            start_ok = v['start'] <= upd
            end_ok = is_na(v['end']) or upd < v['end']
            if start_ok and end_ok:
                covering = v
                break

        if covering is None:
            # upd is earlier than the account's earliest version
            f = min(vlist, key=lambda v: v['start'])
            vlist.append({
                'plan': plan,
                'start': upd,
                'end': f['start'],
                'is_current': 0,
            })
        else:
            v = covering
            if plan_eq(v['plan'], plan):
                # no-op: unchanged attribute, no new version
                pass
            elif upd == v['start']:
                # same-day correction, no new version
                v['plan'] = plan
            else:
                # split v at upd
                vlist.append({
                    'plan': plan,
                    'start': upd,
                    'end': v['end'],
                    'is_current': v['is_current'],
                })
                v['end'] = upd
                v['is_current'] = 0

    records = []
    for acc, vlist in versions.items():
        for v in vlist:
            records.append({
                'account_id': acc,
                'plan': v['plan'],
                'eff_start_date': v['start'],
                'eff_end_date': v['end'],
                'is_current': v['is_current'],
            })

    out = pd.DataFrame(
        records,
        columns=['account_id', 'plan', 'eff_start_date', 'eff_end_date', 'is_current'],
    )

    if len(out) > 0:
        out = out.sort_values(
            by=['account_id', 'eff_start_date'], kind='mergesort'
        ).reset_index(drop=True)

    return {'dim_account_out': out}
